result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_bridges.py", "content": "import random

import pytest

from bridges import bridges_and_cut_vertices


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

def count_components(n, edges):
    """Number of connected components of graph (n, edges)."""
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
    return len({find(x) for x in range(n)})


def brute_force(n, edges):
    """Reference answers via deletion experiments."""
    edges = [(u, v) for u, v in edges if u != v]

    base_cc = count_components(n, edges)

    true_bridges = set()
    for i, (u, v) in enumerate(edges):
        rest = edges[:i] + edges[i + 1:]
        if count_components(n, rest) > base_cc:
            true_bridges.add(frozenset((u, v)))

    true_cuts = set()
    for v in range(n):
        rest = [(a, b) for a, b in edges if a != v and b != v]
        # removing an isolated vertex does not increase components
        baseline = base_cc - (1 if all(v not in e for e in edges) else 0)
        # count components among remaining vertices only
        remap = {x: k for k, x in enumerate(sorted(set(range(n)) - {v}))}
        remapped = [(remap[a], remap[b]) for a, b in rest]
        cc_without_v = count_components(len(remap), remapped)
        if cc_without_v > baseline:
            true_cuts.add(v)

    return true_bridges, true_cuts


# ---------------------------------------------------------------------------
# Layer 1: hand-built cases
# ---------------------------------------------------------------------------

class TestHandBuilt:
    def test_two_triangles_joined_by_one_edge(self):
        # triangles 0-1-2 and 3-4-5 joined by bridge 2-3
        edges = [(0, 1), (1, 2), (2, 0),
                 (3, 4), (4, 5), (5, 3),
                 (2, 3)]
        bridges, cuts = bridges_and_cut_vertices(6, edges)
        assert bridges == {frozenset((2, 3))}
        assert cuts == {2, 3}

    def test_star(self):
        # center 0 with leaves 1..5
        edges = [(0, i) for i in range(1, 6)]
        bridges, cuts = bridges_and_cut_vertices(6, edges)
        assert bridges == {frozenset((0, i)) for i in range(1, 6)}
        assert cuts == {0}

    def test_cycle_has_nothing(self):
        edges = [(i, (i + 1) % 7) for i in range(7)]
        bridges, cuts = bridges_and_cut_vertices(7, edges)
        assert bridges == set()
        assert cuts == set()

    def test_two_components(self):
        # path 0-1-2 plus triangle 3-4-5
        edges = [(0, 1), (1, 2), (3, 4), (4, 5), (5, 3)]
        bridges, cuts = bridges_and_cut_vertices(6, edges)
        assert bridges == {frozenset((0, 1)), frozenset((1, 2))}
        assert cuts == {1}

    def test_parallel_edges_never_a_bridge(self):
        # double edge 0-1, single pendant chain 1-2-3
        edges = [(0, 1), (0, 1), (1, 2), (2, 3)]
        bridges, cuts = bridges_and_cut_vertices(4, edges)
        assert bridges == {frozenset((1, 2)), frozenset((2, 3))}
        assert cuts == {1, 2}

    def test_parallel_only_component(self):
        # two vertices joined by three parallel edges
        edges = [(0, 1)] * 3
        bridges, cuts = bridges_and_cut_vertices(2, edges)
        assert bridges == set()
        assert cuts == set()

    def test_self_loops_ignored(self):
        edges = [(0, 0), (0, 1), (1, 1), (1, 2)]
        bridges, cuts = bridges_and_cut_vertices(3, edges)
        assert bridges == {frozenset((1, 2))}
        assert cuts == {1}

    def test_empty_graph_and_isolated_vertices(self):
        assert bridges_and_cut_vertices(0, []) == (set(), set())
        assert bridges_and_cut_vertices(3, []) == (set(), set())

    def test_single_edge(self):
        bridges, cuts = bridges_and_cut_vertices(2, [(0, 1)])
        assert bridges == {frozenset((0, 1))}
        assert cuts == set()


# ---------------------------------------------------------------------------
# Layer 2: brute-force cross-check on seeded random graphs
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("seed", range(300))
def test_random_graphs_against_brute_force(seed):
    rng = random.Random(seed)
    n = rng.randint(1, 10)
    density = rng.choice([0.1, 0.2, 0.35])
    m = rng.randint(0, int(density * n * (n - 1)) + n // 2)
    edges = []
    for _ in range(m):
        u, v = rng.randrange(n), rng.randrange(n)
        edges.append((u, v))  # may create self-loops / parallel edges

    got_bridges, got_cuts = bridges_and_cut_vertices(n, edges)
    want_bridges, want_cuts = brute_force(n, edges)

    assert got_bridges == want_bridges, (
        f"seed={seed} n={n} edges={edges}: bridges {got_bridges} != {want_bridges}"
    )
    assert got_cuts == want_cuts, (
        f"seed={seed} n={n} edges={edges}: cuts {got_cuts} != {want_cuts}"
    )
